$function$

CREATE OR REPLACE FUNCTION public.erp_financial_v2_reverse_journal_u2c3_internal(p_operation_id uuid, p_company_id uuid, p_device_id text, p_journal_entry_id uuid, p_reason text, p_local_created_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_existing public.erp_operations_commands%rowtype; v_source public.erp_financial_journal_entries%rowtype; v_lines jsonb;
 v_reverse_id uuid; v_records jsonb:='[]'; v_result jsonb; v_now timestamptz:=clock_timestamp();
begin
 perform public.erp_financial_v2_assert_access(p_company_id); perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text,0));
 select * into v_existing from public.erp_operations_commands where operation_id=p_operation_id and company_id=p_company_id; if found then return v_existing.result; end if;
 select * into v_source from public.erp_financial_journal_entries where company_id=p_company_id and journal_entry_id=p_journal_entry_id for update;
 if not found then raise exception using errcode='P0002',message='FINANCE_V2_JOURNAL_NOT_FOUND'; end if;
 if v_source.status<>'POSTED' then raise exception using errcode='23514',message='FINANCE_V2_JOURNAL_NOT_POSTED'; end if;
 if nullif(btrim(p_reason),'') is null then raise exception using errcode='22023',message='FINANCE_V2_REVERSAL_REASON_REQUIRED'; end if;
 select jsonb_agg(jsonb_build_object('accountCode',account_code,'debit',credit,'credit',debit,'costCenter',cost_center,
  'auxiliary',auxiliary,'lineDescription','Reverso: '||description,'documentReference',document_reference) order by line_number) into v_lines
 from public.erp_financial_journal_lines where company_id=p_company_id and journal_entry_id=p_journal_entry_id;
 v_reverse_id:=public.erp_financial_v2_create_entry_internal(p_company_id,p_operation_id,p_device_id,
  jsonb_build_object('accountingDate',current_date,'concept','Reverso de '||v_source.entry_number||' - '||v_source.concept,
   'originModule','Ajustes','sourceDocument',v_source.source_document,'externalReference',v_source.entry_number,
   'currencyCode',v_source.currency_code,'exchangeRate',v_source.exchange_rate,'lines',v_lines,'observation',p_reason),
  'JOURNAL_ENTRY',p_journal_entry_id::text,'REVERSE_JOURNAL');
 update public.erp_financial_journal_entries set status='REVERSED',reversed_at=v_now,reversed_by=auth.uid(),version=version+1,
  last_operation_id=p_operation_id where company_id=p_company_id and journal_entry_id=p_journal_entry_id;
 update public.erp_financial_journal_entries set reverse_of_id=p_journal_entry_id where company_id=p_company_id and journal_entry_id=v_reverse_id;
 v_records:=v_records||jsonb_build_array(public.erp_financial_v2_publish_entry(p_company_id,p_operation_id,p_device_id,p_journal_entry_id))
  ||jsonb_build_array(public.erp_financial_v2_publish_entry(p_company_id,p_operation_id,p_device_id,v_reverse_id))
  ||jsonb_build_array(public.erp_financial_v2_write_event(p_company_id,p_operation_id,p_device_id,'REVERSE_JOURNAL','JOURNAL_ENTRY',p_journal_entry_id::text,jsonb_build_object('reverseJournalEntryId',v_reverse_id::text,'reason',p_reason)));
 v_result:=jsonb_build_object('ok',true,'serverTime',clock_timestamp(),'records',v_records,'result',jsonb_build_object('journalEntryId',p_journal_entry_id::text,'reverseJournalEntryId',v_reverse_id::text));
 insert into public.erp_operations_commands(operation_id,company_id,command_type,source_record_id,request_payload,result,status,user_id,device_id,local_created_at,server_created_at)
 values(p_operation_id,p_company_id,'FINANCE_REVERSE_JOURNAL',p_journal_entry_id::text,jsonb_build_object('reason',p_reason),v_result,'CONFIRMED',auth.uid(),p_device_id,p_local_created_at,clock_timestamp()); return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.erp_financial_v2_validate_account(p_company_id uuid, p_code text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_payload jsonb;
begin
  select payload into v_payload from public.erp_entity_records
   where company_id=p_company_id and entity='accounting_chart_accounts' and deleted_at is null
     and coalesce(payload->>'code',record_id)=btrim(p_code) limit 1;
  if not found then raise exception using errcode='23503',message='FINANCE_V2_ACCOUNT_NOT_FOUND:'||btrim(p_code); end if;
  if lower(coalesce(v_payload->>'status','activa')) not in ('activa','active')
     or lower(coalesce(v_payload->>'isMovement',v_payload->>'is_movement','false')) not in ('true','1') then
    raise exception using errcode='23514',message='FINANCE_V2_ACCOUNT_NOT_POSTABLE:'||btrim(p_code);
  end if;
  return coalesce(v_payload->>'name',btrim(p_code));
end $function$

CREATE OR REPLACE FUNCTION public.erp_operations_v2_write_record(p_company_id uuid, p_operation_id uuid, p_device_id text, p_entity text, p_record_id text, p_payload jsonb, p_base_version bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_current public.erp_entity_records%rowtype;
  v_saved public.erp_entity_records%rowtype;
  v_next_version bigint;
  v_now timestamptz := clock_timestamp();
  v_payload jsonb;
begin
  if nullif(btrim(p_entity), '') is null
     or nullif(btrim(p_record_id), '') is null
     or jsonb_typeof(coalesce(p_payload, '{}'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'OPERATIONS_V2_RECORD_INVALID';
  end if;

  select * into v_current
  from public.erp_entity_records record
  where record.company_id = p_company_id
    and record.entity = p_entity
    and record.record_id = p_record_id
  for update;

  if found and v_current.version <> greatest(coalesce(p_base_version, 0), 0) then
    raise exception using errcode = 'PT409',
      message = format('OPERATIONS_V2_VERSION_CONFLICT:%s:%s:SERVER_%s:CLIENT_%s', p_entity, p_record_id, v_current.version, coalesce(p_base_version, 0));
  end if;
  if not found and coalesce(p_base_version, 0) > 0 then
    raise exception using errcode = 'PT409',
      message = format('OPERATIONS_V2_RECORD_MISSING:%s:%s', p_entity, p_record_id);
  end if;

  v_next_version := coalesce(v_current.version, 0) + 1;
  v_payload := coalesce(p_payload, '{}'::jsonb) || jsonb_build_object(
    'operation_id', p_operation_id::text,
    'company_id', p_company_id::text,
    'serverUpdatedAt', v_now,
    'updatedAt', to_char(v_now at time zone 'America/Guayaquil', 'YYYY-MM-DD HH24:MI:SS')
  );

  insert into public.erp_entity_records(
    company_id, entity, record_id, payload, version, created_by, updated_by,
    deleted_at, device_id, last_operation_id
  ) values (
    p_company_id, p_entity, p_record_id, v_payload, v_next_version,
    auth.uid(), auth.uid(), null, p_device_id, p_operation_id
  )
  on conflict (company_id, entity, record_id) do update set
    payload = excluded.payload,
    version = v_next_version,
    updated_at = v_now,
    updated_by = auth.uid(),
    deleted_at = null,
    device_id = p_device_id,
    last_operation_id = p_operation_id;

  select * into v_saved
  from public.erp_entity_records record
  where record.company_id = p_company_id
    and record.entity = p_entity
    and record.record_id = p_record_id;

  return to_jsonb(v_saved);
end;
$function$

CREATE OR REPLACE FUNCTION public.erp_purchase_withholding_assert_accounts(p_company_id uuid, p_issue_date date, p_source jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_line jsonb;
  v_param public.erp_entity_records%rowtype;
  v_account public.erp_entity_records%rowtype;
  v_matches integer;
  v_type text;
  v_code text;
  v_rate numeric;
  v_amount numeric;
  v_total numeric := 0;
  v_expected jsonb := '{}'::jsonb;
  v_actual jsonb := '{}'::jsonb;
  v_debit numeric := 0;
  v_payable text;
  v_meta jsonb;
  v_name text;
  v_named_rate text[];
begin
  select ap.payable_account_code into v_payable
    from public.erp_supplier_purchase_documents p
    join public.erp_supplier_accounts_payable ap
      on ap.company_id=p.company_id and ap.payable_id=p.payable_id
   where p.company_id=p_company_id
     and p.purchase_document_id=(p_source #>> '{erpPurchase,purchaseDocumentId}')::uuid;
  if nullif(btrim(v_payable),'') is null then
    raise exception 'RETENTION_PURCHASE_PAYABLE_REQUIRED';
  end if;
  if p_issue_date is null or jsonb_typeof(p_source #> '{withholding,supportingDocuments}') is distinct from 'array'
     or jsonb_typeof(p_source #> '{erpPurchase,journal,lines}') is distinct from 'array' then
    raise exception 'RETENTION_ACCOUNT_CONTRACT_REQUIRED';
  end if;
  for v_line in select r.value from jsonb_array_elements(p_source #> '{withholding,supportingDocuments}') d
    cross join lateral jsonb_array_elements(d.value->'retentions') r
  loop
    v_type := case v_line->>'code' when '1' then 'RENTA' when '2' then 'IVA' end;
    v_code := v_line->>'retentionCode';
    v_rate := (v_line->>'rate')::numeric;
    v_amount := (v_line->>'value')::numeric;
    select count(*) into v_matches from public.erp_entity_records p
      where p.company_id=p_company_id and p.entity='accounting_retention_parameters' and p.deleted_at is null
        and p.payload->>'taxType'=v_type and p.payload->>'sriCode'=v_code
        and p.payload->>'status'='activo'
        and nullif(p.payload->>'effectiveFrom','')::date<=p_issue_date
        and (nullif(p.payload->>'effectiveTo','') is null or (p.payload->>'effectiveTo')::date>=p_issue_date);
    if v_matches<>1 then raise exception 'RETENTION_PARAMETER_REQUIRED: % / %',v_type,v_code; end if;
    select * into strict v_param from public.erp_entity_records p
      where p.company_id=p_company_id and p.entity='accounting_retention_parameters' and p.deleted_at is null
        and p.payload->>'taxType'=v_type and p.payload->>'sriCode'=v_code and p.payload->>'status'='activo'
        and nullif(p.payload->>'effectiveFrom','')::date<=p_issue_date
        and (nullif(p.payload->>'effectiveTo','') is null or (p.payload->>'effectiveTo')::date>=p_issue_date)
      for share;
    if v_rate is null or v_rate is distinct from (v_param.payload->>'percentage')::numeric
       or v_amount is null or v_amount is distinct from round((v_line->>'taxableBase')::numeric*v_rate/100,2) then
      raise exception 'RETENTION_PARAMETER_CONFLICT: %',v_code;
    end if;
    if v_type='RENTA' and v_code='332' and v_rate=0 and v_amount=0 then continue; end if;
    if v_rate<=0 or v_amount<=0 then raise exception 'RETENTION_POSITIVE_AMOUNT_REQUIRED'; end if;
    select count(*) into v_matches from public.erp_entity_records a
      where a.company_id=p_company_id and a.entity='accounting_chart_accounts' and a.deleted_at is null
        and a.payload->>'code'=nullif(btrim(v_param.payload->>'payableAccountCode'),'');
    if v_matches<>1 then
      raise exception 'RETENTION_PARAMETER_ACCOUNT_REQUIRED: Configure la cuenta contable para la retención % / %%% antes de crear el comprobante.',v_code,v_rate;
    end if;
    select * into strict v_account from public.erp_entity_records a
      where a.company_id=p_company_id and a.entity='accounting_chart_accounts' and a.deleted_at is null
        and a.payload->>'code'=v_param.payload->>'payableAccountCode' for share;
    v_name := upper(coalesce(v_account.payload->>'name',''));
    if lower(coalesce(v_account.payload->>'status','')) not in ('activa','active')
       or (v_account.payload->>'isMovement') is distinct from 'true'
       or lower(coalesce(v_account.payload->>'type',''))<>'pasivo'
       or lower(coalesce(v_account.payload->>'nature',''))<>'acreedora'
       or (v_type='RENTA' and v_name ~ '\mIVA\M')
       or (v_type='IVA' and v_name ~ '\mIR\M|IMPUESTO A LA RENTA') then
      raise exception 'RETENTION_PARAMETER_ACCOUNT_INCOMPATIBLE: % / %',v_code,v_param.payload->>'payableAccountCode';
    end if;
    for v_named_rate in select regexp_matches(v_name,'([0-9]+(?:[.,][0-9]+)?)\s*%','g') loop
      if replace(v_named_rate[1],',','.')::numeric<>v_rate then
        raise exception 'RETENTION_PARAMETER_ACCOUNT_PERCENTAGE_CONFLICT: %',v_code;
      end if;
    end loop;
    -- Optional new-client snapshot detects a stale mapping. Old clients cannot
    -- bypass the canonical lookup or journal comparison by omitting metadata.
    if p_source #> '{erpPurchase,retentionAccounts}' is not null then
      select m.value into v_meta from jsonb_array_elements(p_source #> '{erpPurchase,retentionAccounts}') m
        where m.value->>'parameterId'=v_param.record_id and m.value->>'code'=v_code limit 1;
      if v_meta is null or v_meta->>'payableAccountCode' is distinct from v_account.payload->>'code'
         or (v_meta->>'parameterVersion')::bigint is distinct from v_param.version then
        raise exception 'RETENTION_PARAMETER_ACCOUNT_STALE: actualice la retención % antes de continuar.',v_code;
      end if;
    end if;
    v_code := v_account.payload->>'code';
    v_expected := jsonb_set(v_expected,array[v_code],to_jsonb(coalesce((v_expected->>v_code)::numeric,0)+v_amount));
    v_total := v_total+v_amount;
  end loop;
  if v_total<=0 then raise exception 'RETENTION_POSITIVE_AMOUNT_REQUIRED: 332 / 0%% no genera comprobante'; end if;
  for v_line in select value from jsonb_array_elements(p_source #> '{erpPurchase,journal,lines}') loop
    v_code := v_line->>'accountCode';
    if v_code is null or coalesce((v_line->>'debit')::numeric,0)<0 or coalesce((v_line->>'credit')::numeric,0)<0
       or (coalesce((v_line->>'debit')::numeric,0)>0 and coalesce((v_line->>'credit')::numeric,0)>0) then
      raise exception 'RETENTION_JOURNAL_ACCOUNT_MISMATCH';
    end if;
    if coalesce((v_line->>'debit')::numeric,0)>0 then
      if v_code<>v_payable then raise exception 'RETENTION_PURCHASE_PAYABLE_MISMATCH'; end if;
      v_debit := v_debit+(v_line->>'debit')::numeric;
    elsif coalesce((v_line->>'credit')::numeric,0)>0 then
      v_actual := jsonb_set(v_actual,array[v_code],to_jsonb(coalesce((v_actual->>v_code)::numeric,0)+(v_line->>'credit')::numeric));
    else raise exception 'RETENTION_JOURNAL_ACCOUNT_MISMATCH';
    end if;
  end loop;
  if v_debit<>v_total or v_actual<>v_expected then raise exception 'RETENTION_JOURNAL_ACCOUNT_MISMATCH'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.erp_purchase_withholding_v2_detail_u2c3_internal(p_company_id uuid, p_purchase_document_id uuid DEFAULT NULL::uuid, p_electronic_document_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_purchase public.erp_supplier_purchase_documents%rowtype;
  v_provider public.erp_supplier_providers%rowtype;
  v_link public.erp_supplier_purchase_withholding_links%rowtype;
  v_document public.electronic_documents%rowtype;
  v_journal public.erp_financial_journal_entries%rowtype;
begin
  if not exists (
    select 1
    from public.user_company_memberships membership
    where membership.company_id = p_company_id
      and membership.user_id = auth.uid()
      and membership.membership_status = 'ACTIVE'
  ) then
    raise exception using errcode = '42501', message = 'SUPPLIER_WITHHOLDING_V2_ACCESS_DENIED';
  end if;
  if p_purchase_document_id is null and p_electronic_document_id is null then
    raise exception using errcode = '22023', message = 'SUPPLIER_WITHHOLDING_V2_DETAIL_ID_REQUIRED';
  end if;

  if p_electronic_document_id is not null then
    select * into v_link
    from public.erp_supplier_purchase_withholding_links link
    where link.company_id = p_company_id
      and link.electronic_document_id = p_electronic_document_id;
    if not found then
      raise exception using errcode = '23503', message = 'SUPPLIER_WITHHOLDING_V2_LINK_NOT_FOUND';
    end if;
    if p_purchase_document_id is not null and p_purchase_document_id <> v_link.purchase_document_id then
      raise exception using errcode = '23514', message = 'SUPPLIER_WITHHOLDING_V2_DETAIL_MISMATCH';
    end if;
    p_purchase_document_id := v_link.purchase_document_id;
  else
    select * into v_link
    from public.erp_supplier_purchase_withholding_links link
    where link.company_id = p_company_id
      and link.purchase_document_id = p_purchase_document_id;
  end if;

  select * into v_purchase
  from public.erp_supplier_purchase_documents purchase
  where purchase.company_id = p_company_id
    and purchase.purchase_document_id = p_purchase_document_id;
  if not found then
    raise exception using errcode = '23503', message = 'SUPPLIER_WITHHOLDING_V2_PURCHASE_NOT_FOUND';
  end if;

  select * into v_provider
  from public.erp_supplier_providers provider
  where provider.company_id = p_company_id
    and provider.provider_id = v_purchase.provider_id;

  if v_link.electronic_document_id is not null then
    select * into v_document
    from public.electronic_documents document
    where document.company_id = p_company_id
      and document.id = v_link.electronic_document_id
      and document.document_type = '07';
    select * into v_journal
    from public.erp_financial_journal_entries journal
    where journal.company_id = p_company_id
      and journal.journal_entry_id = v_link.journal_entry_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'purchase', to_jsonb(v_purchase),
    'provider', to_jsonb(v_provider),
    'lines', coalesce((
      select jsonb_agg(to_jsonb(line) order by line.line_number)
      from public.erp_supplier_purchase_lines line
      where line.company_id = p_company_id
        and line.purchase_document_id = v_purchase.purchase_document_id
    ), '[]'::jsonb),
    'link', case when v_link.purchase_document_id is null then null else to_jsonb(v_link) end,
    'document', case when v_document.id is null then null else to_jsonb(v_document) end,
    'journal', case when v_journal.journal_entry_id is null then null else to_jsonb(v_journal) end,
    'journalLines', case when v_journal.journal_entry_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(line) order by line.line_number)
      from public.erp_financial_journal_lines line
      where line.company_id = p_company_id
        and line.journal_entry_id = v_journal.journal_entry_id
    ), '[]'::jsonb) end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.erp_security_assert_capability(p_company_id uuid, p_capability_id text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform public.erp_u2a_assert_company_read_access(p_company_id);
  if not exists (
    select 1 from public.erp_security_capabilities capability
    where capability.capability_id = p_capability_id and capability.active
  ) then
    raise exception using errcode = '42501', message = 'ACTIVE_CAPABILITY_REQUIRED';
  end if;
  if not public.erp_security_has_capability(p_company_id, p_capability_id) then
    raise exception using errcode = '42501', message = 'CAPABILITY_REQUIRED';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.erp_u2c3_assert_mutation_capability(p_rpc_name text, p_company_id uuid, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_rule public.erp_u2c3_mutation_rpc_capabilities%rowtype;
  v_command_rule public.erp_u2c3_operations_command_capabilities%rowtype;
  v_capability text;
  v_specific_capability text;
  v_entity text := nullif(btrim(coalesce(p_context->>'entity','')), '');
  v_action text := upper(btrim(coalesce(p_context->>'action','')));
  v_record_id text := nullif(btrim(coalesce(p_context->>'record_id','')), '');
  v_command text := upper(btrim(coalesce(p_context->>'command','')));
  v_payload jsonb := coalesce(p_context->'payload','{}'::jsonb);
  v_exists boolean := false;
begin
  select * into v_rule from public.erp_u2c3_mutation_rpc_capabilities where rpc_name=p_rpc_name;
  if not found then
    raise exception using errcode='42501',message='U2C3_MUTATION_RPC_UNMAPPED';
  end if;

  if v_rule.resolution_strategy in ('FIXED','SRI_INTERACTIVE') then
    v_capability := v_rule.capability_id;
  elsif v_rule.resolution_strategy='COMMERCIAL_ORDER_STATE' then
    if v_record_id is null then raise exception using errcode='22023',message='U2C3_COMMERCIAL_RECORD_REQUIRED'; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':U2C3:COMMERCIAL_ORDER:'||v_record_id,0));
    select exists(select 1 from public.erp_entity_records r where r.company_id=p_company_id and r.entity='commercial_orders' and r.record_id=v_record_id and r.deleted_at is null) into v_exists;
    v_capability := case when v_exists then 'commercial.orders.edit' else 'commercial.orders.create' end;
  elsif v_rule.resolution_strategy='OPERATIONS_COMMAND' then
    select * into v_command_rule from public.erp_u2c3_operations_command_capabilities where command=v_command;
    if not found then raise exception using errcode='42501',message='U2C3_OPERATIONS_COMMAND_UNMAPPED'; end if;
    if v_command_rule.resolution_strategy='RECEPTION_STATE' then
      v_record_id := nullif(btrim(coalesce(v_payload->>'receptionId','')), '');
      if v_record_id is null then raise exception using errcode='22023',message='U2C3_RECEPTION_RECORD_REQUIRED'; end if;
      perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':U2C3:RECEPTION:'||v_record_id,0));
      select exists(select 1 from public.erp_entity_records r where r.company_id=p_company_id and r.entity='operations_receptions' and r.record_id=v_record_id and r.deleted_at is null) into v_exists;
      v_capability := case when v_exists then 'operations.reception.edit' else 'operations.reception.create' end;
    else
      v_capability := v_command_rule.capability_id;
    end if;
  elsif v_rule.resolution_strategy='OFFLINE_ENTITY_ACTION' then
    if v_entity is null or v_record_id is null or v_action not in ('INSERT','UPDATE','DELETE') then
      raise exception using errcode='42501',message='U2C3_OFFLINE_ACTION_UNMAPPED';
    end if;
    perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':U2C3:OFFLINE:'||v_entity||':'||v_record_id,0));
    if v_entity='commercial_orders' and v_action in ('INSERT','UPDATE') then
      select exists(select 1 from public.erp_entity_records r where r.company_id=p_company_id and r.entity=v_entity and r.record_id=v_record_id and r.deleted_at is null) into v_exists;
      v_capability := case when v_exists then 'commercial.orders.edit' else 'commercial.orders.create' end;
    elsif v_entity='commercial_orders' and v_action='DELETE' then
      v_capability := 'commercial.orders.cancel';
    else
      select capability_id into v_capability
      from public.erp_u2c3_offline_action_capabilities
      where entity=v_entity and action=v_action;

      v_specific_capability := case v_entity
        when 'operations_suppliers' then 'operations.farms_blocks.manage'
        when 'operations_classifiers' then 'operations.classifiers.manage'
        when 'operations_bunchers' then 'operations.bunchers.manage'
        when 'operations_receptionists' then 'operations.receptionists.manage'
        when 'operations_digitizers' then 'operations.digitizers.manage'
        when 'operations_scanners' then 'operations.scanners.manage'
        when 'operations_responsibles' then 'operations.responsibles.manage'
        when 'operations_varieties' then 'operations.varieties.manage'
        when 'operations_lengths' then 'operations.lengths.manage'
        when 'operations_stem_types' then 'operations.stem_types.manage'
        when 'operations_label_types' then 'operations.label_types.manage'
        else null
      end;
    end if;
  end if;

  if v_capability is null then
    raise exception using errcode='42501',message='U2C3_MUTATION_ACTION_UNMAPPED';
  end if;

  if v_specific_capability is not null then
    perform public.erp_security_assert_capability(p_company_id, 'operations.parameters.view');
    perform public.erp_security_assert_capability(p_company_id, v_specific_capability);
    return;
  end if;

  perform public.erp_security_assert_capability(p_company_id,v_capability);
end;
$function$

CREATE OR REPLACE FUNCTION public.erp_warehouse_v2_assert_access(p_company_id uuid)
 RETURNS void
 LANGUAGE plpgsql
